// ioperm(from, num, turn_on)
// Sets I/O port permissions (i386 only)

unsigned long base_port = 0x378;  // LPT port example
unsigned long num_ports = 4;      // Range: 0x378 - 0x37B

// 1. Enable permissions (requires root/CAP_SYS_RAWIO)
int enable = 1;
int ret = ioperm(base_port, num_ports, enable);

if (ret != 0) {
    // Error check: ret == -1
    // Common failure: EPERM (Insufficient privileges)
    return errno;
}

// 2. Disable permissions (Cleanup/Resource release)
int disable = 0;
ioperm(base_port, num_ports, disable);
// Disabling generally succeeds.
